import React, { useState, useEffect } from "react";
import "./Seo_shortform.css";

function SEO({ videoThumbnail }) {
  // Hardcoded mock data for testing
  const mockData = {
    message: "Processing completed successfully",
    results: {
      clip1: {
        seo: {
          keywords: ["SEO", "Video"],
          description: "A description for clip1",
          title: "Title for clip1",
          tags: ["tag1", "tag2"]
        },
        video_upscaling: { output_path: "/path/to/video/clip1" },
        audio_processing: { output_path: "/path/to/audio/clip1" }
      },
      clip2: {
        seo: {
          keywords: ["Clip", "Content"],
          description: "A description for clip2",
          title: "Title for clip2",
          tags: ["tag3", "tag4"]
        },
        video_upscaling: { output_path: "/path/to/video/clip2" },
        audio_processing: { output_path: "/path/to/audio/clip2" }
      }
    }
  };

  const { message, results } = mockData;

  const [seoMessage, setSeoMessage] = useState(message || "No SEO data received.");

  // Debugging: Log the received results for verification
  useEffect(() => {
    console.log("Received results:", results);
  }, [results]);

  return (
    <div className="seo-app">
      {/* Header Section */}
      <header className="header">
        <h1 className="logo">
          <span className="bold">Channel-</span>
          <span className="highlight">IQ</span>
        </h1>
        <nav className="nav">
          <a href="#clipper">Clipper</a>
          <a href="#seo">SEO</a>
          <a href="#thumbnail">Thumbnail</a>
          <a href="#pricing">Pricing</a>
          <button className="sign-in">Sign in</button>
          <button className="sign-up">Sign up</button>
        </nav>
      </header>

      {/* Main Content Section */}
      <main className="main-content">
        {/* Navigation to Clipper */}
        <button className="clipper-btn">Go to Clipper</button>

        {/* Clip Section */}
        <div className="clip-section">
          {/* Image Preview */}
          <div className="image-preview">
            <img
              src={videoThumbnail || "https://via.placeholder.com/300x300"}
              alt="Video Thumbnail"
              className="preview-image"
            />
          </div>

          {/* Clip Customization */}
          <div className="customize-clip">
            {/* SEO Data Display for Multiple Clips */}
            {Object.entries(results || {}).map(([clipId, clipData], index) => {
              const seoData = clipData?.seo || {};
              const keywords = seoData.keywords?.length ? seoData.keywords.join(", ") : "No keywords available.";
              const description = seoData.description || "No description available.";
              const title = seoData.title || "No title available.";
              const tags = seoData.tags?.length ? seoData.tags.join(", ") : "No tags available.";

              // Video upscaling and audio processing
              const videoUpscalingPath = clipData?.video_upscaling?.output_path || "No video output path available.";
              const audioProcessingPath = clipData?.audio_processing?.output_path || "No audio output path available.";

              return (
                <div key={index} className="clip-container">
                  <div className="seo-box">
                    <h2>Clip {index + 1} - Keywords</h2>
                    <p>{keywords}</p>
                  </div>
                  <div className="seo-box">
                    <h2>Clip {index + 1} - Description</h2>
                    <p>{description}</p>
                  </div>
                  <div className="seo-box">
                    <h2>Clip {index + 1} - Title</h2>
                    <p>{title}</p>
                  </div>
                  <div className="seo-box">
                    <h2>Clip {index + 1} - Tags</h2>
                    <p>{tags}</p>
                  </div>

                  {/* Video Upscaling and Audio Processing */}
                  <div className="seo-box">
                    <h2>Clip {index + 1} - Video Upscaling</h2>
                    <p>{videoUpscalingPath}</p>
                  </div>
                  <div className="seo-box">
                    <h2>Clip {index + 1} - Audio Processing</h2>
                    <p>{audioProcessingPath}</p>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </main>
    </div>
  );
}

export default SEO;
